package com.chatserver.core

import io.ktor.server.application.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import kotlinx.serialization.*
import kotlinx.serialization.json.*
import java.util.concurrent.ConcurrentHashMap

@Serializable
data class ChatMessage(
    val type: String,
    val tenant: String,
    val channel: String,
    val payload: Map<String, JsonElement> = emptyMap()
)

class TenantConfig(
    val tenantId: String,
    private val properties: MutableMap<String, Any?> = mutableMapOf(
        "maxUsers" to 100,
        "rateLimit" to 60,
        "features" to mutableMapOf(
            "fileUpload" to false,
            "reactions" to true,
            "threads" to true
        )
    )
) {
    fun getProperty(path: String): Any? {
        val parts = path.split(".")
        var current: Any? = properties
        for (part in parts) {
            current = when (current) {
                is Map<*, *> -> current[part]
                else -> null
            }
        }
        return current
    }

    fun setProperty(path: String, value: Any?) {
        val parts = path.split(".")
        var current: MutableMap<String, Any?> = properties
        for (i in 0 until parts.size - 1) {
            val next = current[parts[i]]
            current = if (next is MutableMap<*, *>) {
                @Suppress("UNCHECKED_CAST")
                next as MutableMap<String, Any?>
            } else {
                val newMap = mutableMapOf<String, Any?>()
                current[parts[i]] = newMap
                newMap
            }
        }
        current[parts.last()] = value
    }
}

object TenantRegistry {
    private val tenants = ConcurrentHashMap<String, TenantConfig>()
    private val baseDefaults: Map<String, Any?> = mapOf(
        "maxUsers" to 50,
        "rateLimit" to 30,
        "features" to mapOf(
            "fileUpload" to false,
            "reactions" to false,
            "threads" to false
        ),
        "adminAccess" to false
    )

    fun getOrCreate(tenantId: String): TenantConfig {
        return tenants.getOrPut(tenantId) {
            TenantConfig(tenantId, baseDefaults.toMutableMap())
        }
    }

    fun getDefault(key: String): Any? = baseDefaults[key]
}

class MessageRouter {
    private val channels = ConcurrentHashMap<String, MutableSet<DefaultWebSocketSession>>()

    fun subscribe(tenant: String, channel: String, session: DefaultWebSocketSession) {
        val key = "$tenant:$channel"
        channels.getOrPut(key) { ConcurrentHashMap.newKeySet() }.add(session)
    }

    suspend fun broadcast(tenant: String, channel: String, message: String) {
        val key = "$tenant:$channel"
        channels[key]?.forEach { session ->
            try { session.send(Frame.Text(message)) } catch (_: Exception) {}
        }
    }
}

fun Application.configureChatServer() {
    val router = MessageRouter()
    val json = Json { ignoreUnknownKeys = true }
    val allowedConfigKeys = setOf("features.fileUpload", "features.reactions", "features.threads", "maxUsers", "rateLimit")

    install(WebSockets)

    routing {
        webSocket("/chat/{tenant}") {
            val tenantId = call.parameters["tenant"] ?: return@webSocket close(
                CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Missing tenant")
            )
            val config = TenantRegistry.getOrCreate(tenantId)

            for (frame in incoming) {
                if (frame is Frame.Text) {
                    val text = frame.readText()
                    val msg = json.decodeFromString<ChatMessage>(text)

                    when (msg.type) {
                        "subscribe" -> router.subscribe(tenantId, msg.channel, this)
                        "publish" -> {
                            if (((config.getProperty("rateLimit") as? Int) ?: 0) > 0) {
                                router.broadcast(tenantId, msg.channel, text)
                            }
                        }
                        "config.update" -> {
                            val path = msg.payload["path"]?.let {
                                json.decodeFromJsonElement<String>(it)
                            } ?: continue
                            if (path !in allowedConfigKeys) continue
                            val value = msg.payload["value"]?.let {
                                deserializeValue(it)
                            }
                            config.setProperty(path, value)
                        }
                    }
                }
            }
        }
    }
}

fun deserializeValue(element: JsonElement): Any? {
    return when (element) {
        is JsonPrimitive -> when {
            element.isString -> element.content
            element.content == "true" || element.content == "false" -> element.boolean
            element.content.contains(".") -> element.double
            else -> element.int
        }
        is JsonObject -> element.mapValues { (_, v) -> deserializeValue(v) }.toMutableMap()
        is JsonArray -> element.map { deserializeValue(it) }
        else -> null
    }
}
